ExtensionToolsPage::ExtensionToolsPage(PluginHost* host,QWidget* parent):QWidget(parent),host_(host) {
 setObjectName("extensionToolsPage");auto* layout=new QVBoxLayout(this);layout->setContentsMargins(20,16,20,16);auto* top=new QHBoxLayout;auto* back=new QPushButton("‹ Library",this);back->setObjectName("extensionBack");top->addWidget(back);auto* heading=new QLabel("Extension tools",this);auto font=heading->font();font.setPointSize(17);font.setBold(true);heading->setFont(font);top->addWidget(heading,1);extensions_=new QComboBox(this);extensions_->setObjectName("extensionProvider");extensions_->setAccessibleName("Enabled extension");top->addWidget(extensions_);layout->addLayout(top);connect(back,&QPushButton::clicked,this,&ExtensionToolsPage::closed);
 notice_=new QLabel(this);notice_->setWordWrap(true);notice_->setTextFormat(Qt::PlainText);layout->addWidget(notice_);commands_=new QComboBox(this);commands_->setObjectName("extensionCommand");commands_->setAccessibleName("Extension command");layout->addWidget(commands_);inputLabel_=new QLabel("Input text",this);inputLabel_->setTextFormat(Qt::PlainText);layout->addWidget(inputLabel_);input_=new QPlainTextEdit(this);input_->setObjectName("extensionInput");input_->setAccessibleName("Text submitted to the extension");input_->setPlaceholderText("Only this submitted text and your extension preferences are passed to the sandbox.");layout->addWidget(input_,1);auto* actions=new QHBoxLayout;run_=new QPushButton("Run command",this);run_->setObjectName("extensionRun");actions->addWidget(run_);auto* clear=new QPushButton("Clear",this);actions->addWidget(clear);actions->addStretch();layout->addLayout(actions);status_=new QLabel("Choose an enabled extension and command.",this);status_->setObjectName("extensionStatus");status_->setTextFormat(Qt::PlainText);status_->setWordWrap(true);layout->addWidget(status_);resultTitle_=new QLabel("Result",this);resultTitle_->setObjectName("extensionResultTitle");resultTitle_->setTextFormat(Qt::PlainText);layout->addWidget(resultTitle_);output_=new QPlainTextEdit(this);output_->setObjectName("extensionOutput");output_->setReadOnly(true);output_->setAccessibleName("Plain-text extension result");layout->addWidget(output_,1);
 connect(run_,&QPushButton::clicked,this,&ExtensionToolsPage::run);connect(clear,&QPushButton::clicked,this,&ExtensionToolsPage::stopAndClear);connect(input_,&QPlainTextEdit::textChanged,this,[this]{const bool bounded=input_->toPlainText().toUtf8().size()<=65536;run_->setEnabled(!busy_&&!selected().id.isEmpty()&&bounded);if(!bounded)status_->setText("Input exceeds the 64 KiB limit. Shorten it to run the command.");});
 connect(extensions_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{stopAndClear();selectCommand();});connect(commands_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{++generation_;busy_=false;output_->clear();const auto m=selected();int index=commands_->currentIndex();if(index>=0&&index<m.commands.size())inputLabel_->setText(m.commands[index].inputLabel);run_->setEnabled(!m.id.isEmpty()&&input_->toPlainText().toUtf8().size()<=65536);});
 connect(host_,&PluginHost::changed,this,[this](const QString& id){if(extensions_->currentData().toString()==id)stopAndClear();refresh();});refresh();
}
PluginManifest ExtensionToolsPage::selected()const{for(const auto& m:host_->manifests())if(m.protocol=="megavault-actions-v1"&&m.id==extensions_->currentData().toString()&&host_->enabled(m.id))return m;return {};}
void ExtensionToolsPage::refresh(){const auto previous=extensions_->currentData();{QSignalBlocker blocker(extensions_);extensions_->clear();for(const auto& m:host_->manifests())if(m.protocol=="megavault-actions-v1"&&host_->enabled(m.id))extensions_->addItem(m.name,m.id);int index=extensions_->findData(previous);if(index>=0)extensions_->setCurrentIndex(index);}selectCommand();}
void ExtensionToolsPage::selectExtension(const QString& id){refresh();const int index=extensions_->findData(id);if(index>=0)extensions_->setCurrentIndex(index);selectCommand();}
void ExtensionToolsPage::selectCommand(){const auto m=selected();QSignalBlocker blocker(commands_);const auto previous=commands_->currentData();commands_->clear();for(const auto& command:m.commands)commands_->addItem(command.title,command.id);int index=commands_->findData(previous);if(index>=0)commands_->setCurrentIndex(index);notice_->setText(m.id.isEmpty()?"Enable an extension in Settings → Extensions to run local tools.":m.sourceNotice);input_->setEnabled(!m.id.isEmpty());run_->setEnabled(!busy_&&!m.id.isEmpty()&&input_->toPlainText().toUtf8().size()<=65536);if(commands_->currentIndex()>=0)inputLabel_->setText(m.commands[commands_->currentIndex()].inputLabel);}
void ExtensionToolsPage::stopAndClear(){++generation_;busy_=false;input_->clear();output_->clear();resultTitle_->setText("Result");status_->setText("Stopped. Input and result cleared.");run_->setEnabled(!selected().id.isEmpty());}
void ExtensionToolsPage::run(){
 const auto m=selected();const auto command=commands_->currentData().toString();if(busy_||m.id.isEmpty()||command.isEmpty())return;const auto text=input_->toPlainText();if(text.toUtf8().size()>65536){status_->setText("Input exceeds the 64 KiB limit.");return;}
 if(activeCommands.fetch_add(1)>=2){activeCommands.fetch_sub(1);status_->setText("Two extension commands are already running. Try again shortly.");return;}
 QJsonObject preferences;for(const auto& setting:m.settings)preferences[setting.id]=QSettings().value(host_->settingKey(m.id)+"preferences/"+setting.id,setting.defaultValue).toBool();const auto payload=QJsonDocument(QJsonObject{{"text",text},{"settings",preferences}}).toJson(QJsonDocument::Compact).toStdString();const auto source=m.script.toUtf8().toStdString();const auto commandId=command.toUtf8().toStdString();const auto gen=++generation_;busy_=true;run_->setEnabled(false);output_->clear();status_->setText("Running locally in the extension sandbox…");auto* watcher=new QFutureWatcher<extensions::ExecutionResult>(this);
 connect(watcher,&QFutureWatcher<extensions::ExecutionResult>::finished,this,[this,watcher,gen,id=m.id]{const auto result=watcher->result();watcher->deleteLater();if(gen!=generation_||!host_->enabled(id)||selected().id!=id)return;busy_=false;run_->setEnabled(input_->toPlainText().toUtf8().size()<=65536);if(!result.ok){status_->setText("Extension failed: "+QString::fromStdString(result.error));return;}if(result.json.size()>1024*1024){status_->setText("Extension failed: result exceeds 1 MiB.");return;}QJsonParseError error;const auto doc=QJsonDocument::fromJson(QByteArray::fromStdString(result.json),&error);const auto value=doc.object();if(error.error!=QJsonParseError::NoError||!doc.isObject()||!value.value("title").isString()||!value.value("text").isString()||value.value("title").toString().size()>2048){status_->setText("Extension failed: result must contain bounded string fields title and text.");return;}resultTitle_->setText(value.value("title").toString());output_->setPlainText(value.value("text").toString());status_->setText("Done · local result, not saved to disk.");});
 watcher->setFuture(QtConcurrent::run([source,commandId,payload]{struct Release{~Release(){activeCommands.fetch_sub(1);}}release;return extensions::invoke(source,commandId,payload);}));
}
